CREATE TABLE workspaces (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL
);

CREATE TABLE tasks (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  title text NOT NULL
);

CREATE TABLE users (
  id uuid PRIMARY KEY,
  email text NOT NULL UNIQUE,
  display_name text NOT NULL CHECK (length(trim(display_name)) >= 2)
);

INSERT INTO tasks (id, workspace_id, title)
VALUES (gen_random_uuid(), $1, 'Learn INSERT')
RETURNING id, title, done, created_at;

SELECT id, title, done
FROM tasks
WHERE workspace_id = $1 AND done = false;

BEGIN;
UPDATE tasks SET done = true WHERE id = $1;
INSERT INTO audit_log(entity_id, action) VALUES ($1, 'TASK_COMPLETED');
COMMIT;

BEGIN;
SELECT * FROM tasks WHERE id = $1 FOR UPDATE;
UPDATE tasks SET done = true WHERE id = $1;
COMMIT;
